mapper.select:
SELECT id, title, summary, dynasty, keywords, cover_image, heat FROM story WHERE status = 1
AND id NOT IN
#{id}
ORDER BY heat DESC LIMIT #{limit}

SELECT s.id, s.title, s.summary, s.dynasty, s.keywords, s.cover_image, s.heat
FROM story s
WHERE s.status = 1
  AND s.category_id = #{categoryId}
  AND s.id != #{excludeId}
ORDER BY s.heat DESC
LIMIT #{limit}

SELECT id, title, summary, dynasty, keywords, cover_image, heat
FROM story
WHERE status = 1
  AND dynasty = #{dynasty}
  AND id != #{excludeId}
ORDER BY heat DESC
LIMIT #{limit}

SELECT id, title, summary, dynasty, keywords, cover_image, heat
FROM story
WHERE status = 1
  AND id != #{excludeId}
  AND (
      keywords LIKE CONCAT('%', #{keywords}, '%')
      OR title LIKE CONCAT('%', #{keywords}, '%')
  )
ORDER BY heat DESC
LIMIT #{limit}

SELECT DISTINCT story_id
FROM story_user_action
WHERE user_id = #{userId}

SELECT t2.story_id AS storyId, COUNT(DISTINCT t2.user_id) AS coOccurrenceCount, SUM(CASE WHEN t2.action_type = 'like' THEN 3 WHEN t2.action_type = 'fav' THEN 5 ELSE 1 END) AS weight FROM story_user_action t1 INNER JOIN story_user_action t2 ON t1.user_id = t2.user_id AND t1.story_id != t2.story_id WHERE t1.story_id = #{storyId}
AND t2.user_id != #{userId}
GROUP BY t2.story_id ORDER BY coOccurrenceCount DESC, weight DESC LIMIT #{limit}
